head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil52520";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil52520.onpageload' });
    }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_window_onclick
 * @description 「닫기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_window_onclick = function(e){
    try {
        $c.win.closePopup()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil52520.btn_window_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_searchCorpListByBeginIndex
 * @description search Corp List By Begin Index 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_searchCorpListByBeginIndex = async function () {
    const sbmOptions = {
        id: "tx_searchCorpListByBeginIndex",
        method: "post",
        action: "/listInvstg/nwlistForncomAnlrpt.do?method=getNwlistForncomAnlrptComSearch",
        ref: "dma_searchCorpListByBeginIndexReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setCorpInfo
 * @description set Corp Info 처리
 * @param {*} bz_procs_no bz_procs_no
 * @param {*} com_abbrv com_abbrv
 * @param {*} isur_cd isur_cd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCorpInfo = async function (bz_procs_no, com_abbrv, isur_cd) {
    let str = "";
    str += "isurCd : " + isur_cd + "\n";
    str += "comNm : " + com_abbrv + "\n";
    str += "bzProcsNo : " + bz_procs_no + "\n";
    const returnKey = '' + dma_pageContext.get("returnKey") + '';
    try {
        (((scwin.openerScwin()) !== scwin && typeof (scwin.openerScwin()).setCorpInfo === 'function' ? (scwin.openerScwin()).setCorpInfo(bz_procs_no, com_abbrv, isur_cd) : void 0), $c.win.closePopup([bz_procs_no, com_abbrv, isur_cd]));
        $c.win.closePopup();
    } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'jldfil52520' });
        await $c.win.alert("<ERROR>\n\n" + "부모창을 찾을 수가 없습니다. \n\n" + str);
    }
};

/**
 * @method
 * @name searchCorpListByBeginIndex
 * @description search Corp List By Begin Index 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchCorpListByBeginIndex = async function () {
    await scwin.tx_searchCorpListByBeginIndex();
};

/**
 * @method
 * @name opener
 * @description 부모 화면 scope(browserPopup/pageFramePopup 공통 — $c.win.getOpenerScope). 단독 진입이거나 부모가 닫혀 없으면
 * @returns {Object} 부모 화면 scope 또는 빈 scope
 * @hidden N
 */
scwin.opener = function () {
    const scope = ($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null;
    return scope || { getComponentById: function () { return null; }, scwin: {} };
};

/**
 * @method
 * @name openerScwin
 * @description 부모 화면의 scwin(함수·전역 접근용). 부모가 없으면 빈 객체
 * @returns {Object} 부모 scwin 또는 {}
 * @hidden N
 */
scwin.openerScwin = function () {
    return scwin.opener().scwin || {};
};
